import { useEffect } from 'react'
import { usePathname } from 'next/navigation'

export function ViewTransitionProvider({
  children,
}: {
  children: React.ReactNode
}) {
  const pathname = usePathname()

  useEffect(() => {
    // Track navigation history to determine direction
    const handlePopState = () => {
      document.documentElement.classList.add('back-navigation')
      setTimeout(() => {
        document.documentElement.classList.remove('back-navigation')
      }, 500)
    }

    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [])

  useEffect(() => {
    // Detect forward navigation from grid to detail
    if (pathname.startsWith('/product/')) {
      document.documentElement.classList.remove('back-navigation')
    }
  }, [pathname])

  return <>{children}</>
}

